using System;using System.Xml.Linq;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.RegularExpressions;using V15Voice;
public sealed class ProseSpeech:KokoroEngine {
 public int Calls,FailAt=-1;public double Unit=.08;public override void CheckFiles(){}public override Wave Generate(string text,double speed,string output){Calls++;if(Calls==FailAt)throw new Exception("fixture interrupted");int words=text.Split(new[]{' '},StringSplitOptions.RemoveEmptyEntries).Length,n=(int)(words*Unit*24000/speed);return new Wave{Rate=24000,Samples=Enumerable.Range(0,n).Select(i=>(short)(2000*Math.Sin(i*2*Math.PI*220/24000))).ToArray()};}
}
public static class Update146Tests {
 static int count;static string root,work;static bool No(){return false;}static void Check(bool b,string n){if(!b)throw new Exception("FAIL "+n);count++;Console.WriteLine("PASS "+n);}static void Reject(Action f,string n){try{f();}catch{Check(true,n);return;}throw new Exception("FAIL "+n);}
 static RenderOptions Options(){return new RenderOptions{Locked=false,Prose=true,NormalizeLoudness=false,Breathing=BreathMode.None};}
 static ProseSpeech Engine(string state){return new ProseSpeech{Root=root,VoiceName="ADAM",ReferenceText="reference",Archive=new SpeechArchive(state)};}
 public static void Main(string[] args){root=Path.GetFullPath(args[0]);work=Path.Combine(Path.GetTempPath(),"V15_146_"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(work);
  string text=String.Join("\n\n",Enumerable.Range(0,100).Select(i=>"Line"+i+" "+String.Join(" ",Enumerable.Repeat("word",19))+"."));var cues=LongText.Parse(text);Check(cues.Count==100&&cues.Sum(c=>c.Words)==2000,"2000-word TXT preserves all 100 complete sentences");Check(String.Join(" ",cues.Select(c=>c.Text))==Regex.Replace(text,@"\s+"," "),"TXT splitting preserves original words, punctuation and order");Check(cues.All(c=>c.Prose&&c.ParagraphEnd),"Original paragraph endings retained for natural breaks");
  var cases=LongText.Parse("Dr. Smith paid 3.14 dollars in the U.S. yesterday. He left.\n\nA new paragraph starts here.");Check(cases.Count==3&&cases[0].Text.Contains("U.S. yesterday"),"Abbreviations and decimal numbers do not cause false sentence splits");Check(!cases[0].ParagraphEnd&&cases[1].ParagraphEnd&&cases[2].ParagraphEnd,"Paragraph pauses distinguished from sentence boundaries");
  string huge=String.Join(" ",Enumerable.Repeat("extraordinary",500))+".";var bounded=LongText.Parse(huge);Check(bounded.All(c=>c.Text.Length<=900)&&String.Join(" ",bounded.Select(c=>c.Text))==huge,"Extremely long sentence split safely without losing or duplicating words");
  string state=Path.Combine(work,"state");var e=Engine(state);var o=Options();var updates=new List<ReadingProgress>();o.ReadingChanged=r=>updates.Add(r);string outPath=Renderer.Render(cues,e,o,Path.Combine(work,"2000.wav"),(p,m)=>{});Check(e.Calls==100&&cues.All(c=>c.Actual>0&&c.Speed==1),"2000-word prose renders at chosen voice speed without per-cue stretching");Check(FinalAudio.PcmFrames(outPath)==(long)Math.Round(cues.Last().End*24000),"Natural timeline exactly matches exported master frame count");Check(cues.Zip(cues.Skip(1),(a,b)=>b.Start>=a.End).All(b=>b),"Long-form timeline never overlaps adjacent speech");Check(updates.Last().Final&&updates.Last().Done==100&&updates.Last().Words==2000&&updates.Last().AudioSeconds==cues.Last().End,"Side panel ends with exact final duration and complete progress");Check(updates.Where(r=>!r.Final).All(r=>r.EstimateLow<=r.EstimateHigh&&r.AudioSeconds>=0),"Live duration estimates remain ordered and explicitly provisional");
  var resumed=Engine(state);Renderer.Render(LongText.Parse(text),resumed,o,Path.Combine(work,"resume.wav"),(p,m)=>{});Check(resumed.Calls==0,"A new engine or reopened session reuses all finished TXT audio");
  var changed=LongText.Parse(text);changed[40].Text+=" Changed.";var edited=Engine(state);Renderer.Render(changed,edited,o,Path.Combine(work,"edited.wav"),(p,m)=>{});Check(edited.Calls==1,"Editing one sentence regenerates only that sentence");
  var loud=Engine(state);var loudOptions=Options();loudOptions.NormalizeLoudness=true;Renderer.Render(LongText.Parse(text),loud,loudOptions,Path.Combine(work,"volume.wav"),(p,m)=>{});Check(loud.Calls==0,"Changing master loudness does not regenerate speech");
  var selected=cues[0];string part=selected.Text;var before=e.Archive.Get(e,part,1);e.Archive.Refresh=true;e.GetSpeech(part,1,"");e.Archive.Refresh=false;Check(e.Archive.CanRestore(e,part,1),"Regenerating a sentence keeps its previous audio version");Check(e.Archive.Restore(e,part,1)&&e.Archive.Get(e,part,1).Samples.SequenceEqual(before.Samples),"Previous sentence version can be restored");
  selected.VoiceLock=LongText.Signature(e,o,selected);var locked=Engine(state);Renderer.Render(new List<Cue>{selected},locked,o,Path.Combine(work,"locked.wav"),(p,m)=>{});Check(locked.Calls==0,"Locked sentence uses saved audio without regeneration");var newSpeed=Options();newSpeed.BaseSpeed=1.1;Reject(()=>Renderer.Render(new List<Cue>{selected},locked,newSpeed,Path.Combine(work,"locked-change.wav"),(p,m)=>{}),"Changing a locked sentence's voice settings requires unlocking");
  string interruptedState=Path.Combine(work,"interrupted");var interrupted=Engine(interruptedState);interrupted.FailAt=4;Reject(()=>Renderer.Render(LongText.Parse(text),interrupted,o,Path.Combine(work,"failed.wav"),(p,m)=>{}),"Long-form failure rejects incomplete master");var retry=Engine(interruptedState);Renderer.Render(LongText.Parse(text),retry,o,Path.Combine(work,"retry.wav"),(p,m)=>{});Check(retry.Calls==97&&!File.Exists(Path.Combine(work,"failed.wav")),"Retry resumes after the three completed sentences without publishing partial master");
  string cancelledState=Path.Combine(work,"cancelled");var cancelled=Engine(cancelledState);Reject(()=>Renderer.Render(LongText.Parse(text),cancelled,o,Path.Combine(work,"cancelled.wav"),(p,m)=>{if(p>=3)cancelled.Cancelled=true;}),"Cancellation stops long-form generation");var afterCancel=Engine(cancelledState);Renderer.Render(LongText.Parse(text),afterCancel,o,Path.Combine(work,"continued.wav"),(p,m)=>{});Check(afterCancel.Calls<100&&!File.Exists(Path.Combine(work,"cancelled.wav")),"Cancelled project retains completed audio for subsequent continuation");
  var partial=LongText.Parse(String.Join(" ",Enumerable.Range(0,6).Select(i=>"Unique"+i+" "+String.Join(" ",Enumerable.Repeat("word",19))+".")));var slower=Engine(Path.Combine(work,"slower"));slower.Unit=.6;Reject(()=>Renderer.Render(partial,slower,o,Path.Combine(work,"partial-timeline.wav"),(p,m)=>{if(p>=15)slower.Cancelled=true;}),"Cancellation can leave provisional times shorter than measured speech");slower.Cancelled=false;slower.FailAt=-1;Renderer.Render(partial,slower,o,Path.Combine(work,"partial-resumed.wav"),(p,m)=>{});Check(partial.Zip(partial.Skip(1),(a,b)=>b.Start>=a.End).All(b=>b),"Same edited project resumes despite overlapping old provisional time estimates");
  string breath=Path.Combine(work,"breath.wav");new Wave{Rate=24000,Samples=Enumerable.Range(0,4800).Select(i=>(short)(500*Math.Sin(i*.2))).ToArray()}.Write(breath);var breathed=LongText.Parse("First sentence ends here. Second sentence ends here. Third sentence ends here.");var bo=Options();bo.Breathing=BreathMode.Custom;bo.BreathEvery=1;bo.BreathPath=breath;var be=Engine(Path.Combine(work,"breath-state"));Renderer.Render(breathed,be,bo,Path.Combine(work,"breathing.wav"),(p,m)=>{});Check(breathed.Take(2).All(c=>c.Status.Contains("hơi thở"))&&breathed.Zip(breathed.Skip(1),(a,b)=>b.Start>=a.End+.27).All(b=>b),"Natural voice timeline reserves space for breath clips without overlapping next sentence");
  string reference=Path.Combine(root,"voice-reference","vanzai","VANZAI_V15_REFERENCE_10s.wav"),mp3=Path.Combine(work,"sample ! (1).mp3"),m4a=Path.Combine(work,"sample.m4a");AudioProcess.Run(root,"-v error -y -i "+KokoroEngine.Q(reference)+" -c:a libmp3lame "+KokoroEngine.Q(mp3),No);AudioProcess.Run(root,"-v error -y -i "+KokoroEngine.Q(reference)+" -c:a aac "+KokoroEngine.Q(m4a),No);
  foreach(string input in new[]{reference,mp3,m4a,Path.Combine(root,"upload","VANZAI.mp4")}){var wave=UserVoices.Import(root,input,Path.Combine(work,"import-"+Guid.NewGuid().ToString("N")+".wav"),0,6,No);Check(Math.Abs(wave.Duration-6)<.1,"Reference import works for "+Path.GetExtension(input)+" including spaces and punctuation in filenames");}
  string txt=Path.Combine(work,"book.txt");File.WriteAllText(txt,text);var job=BatchJob.Load(txt);Check(!job.Timed&&job.Cues.Count==100&&job.Cues.All(c=>c.Prose),"Queue recognizes plain TXT and uses long-form sentence parser");job.Cues[0].VoiceLock="locked-fixture";string queue=Path.Combine(work,"queue.xml");QueueStore.Save(queue,new[]{job});var loaded=QueueStore.Load(queue)[0];Check(loaded.Cues[0].Prose&&loaded.Cues[0].ParagraphEnd&&loaded.Cues[0].VoiceLock=="locked-fixture","Queue persistence retains prose metadata and paragraph locks");
  var oldQueue=StateFiles.Read(queue);foreach(var c in oldQueue.Elements("job").Elements("cue")){var attr=c.Attribute("prose");if(attr!=null)attr.Remove();}StateFiles.Write(queue,oldQueue);var migrated=QueueStore.Load(queue)[0];Check(migrated.Cues.All(c=>c.Prose),"Older TXT queues migrate safely into natural-text mode without losing edited sentences");
  Console.WriteLine("TOTAL UPDATE 1.4.6 "+count+" passed. Artifacts: "+work);
 }
}
